const clean = (v) => v === null || v === undefined || String(v).trim() === '' ? null : String(v).trim();
return $input.all().map(({ json: r }) => ({ json: {
  id_motoboy: Number(r.id_motoboy),
  nombre: clean(r.nombre),
  condicion: clean(r.condicion),
  flotilla: clean(r.flotilla),
  ultima_reserva: clean(r.ultima_reserva),
  activo: true,
  visto_por_ultima_vez: new Date().toISOString(),
  actualizado_en: new Date().toISOString(),
  ultimo_sync_id: String($execution.id)
} }));

const items = $input.all();
let grupos;
if (items.length === 1 && Array.isArray(items[0].json)) grupos = items[0].json;
else if (items.length === 1 && Array.isArray(items[0].json.data)) grupos = items[0].json.data;
else if (items.length === 1 && Array.isArray(items[0].json.groups)) grupos = items[0].json.groups;
else grupos = items.map(i => i.json);

const validos = grupos.filter(g => String(g.JID || g.id || '').endsWith('@g.us'));
if (validos.length === 0) throw new Error('WAHA no devolvio grupos validos; se cancela el cierre para no desactivar datos vigentes.');

const ahora = new Date().toISOString();
return validos.map(g => {
  const jid = String(g.JID || g.id).trim();
  const nombreGrupo = String(g.Name || g.name || g.subject || '').trim();
  const match = nombreGrupo.match(/^#?(\d+)(?:\s+-?\s*|\s+)(.*)$/);
  return { json: {
    grupo_jid: jid,
    nombre_grupo: nombreGrupo || jid,
    id_extraido: match ? Number(match[1]) : null,
    nombre_extraido: match && match[2] ? match[2].trim() : null,
    activo: true,
    visto_por_ultima_vez: ahora,
    actualizado_en: ahora,
    ultimo_sync_id: String($execution.id)
  } };
});

