BEGIN;

INSERT INTO public.sellers_activos (id_usuario, nombre, hora_corte, direccion, fecha_activacion, celular, comercial, email, lleva_bodega, lleva_dropoff, paga_colecta, tope_maximo, grupo_jid, grupo_nombre, activo, visto_por_ultima_vez, actualizado_en, ultimo_sync_id)
SELECT s.id_seller, s.nombre, s.hora_corte, s.direccion, s.fecha_activacion, s.celular, s.comercial, s.email, s.lleva_bodega, s.lleva_dropoff, s.paga_colecta, s.tope_maximo, a.grupo_jid, g.nombre_grupo, s.activo, s.visto_por_ultima_vez, now(), s.ultimo_sync_id
FROM public.directorio_sellers s
LEFT JOIN public.whatsapp_asignaciones a ON a.tipo_entidad = 'SELLER' AND a.id_entidad = s.id_seller
LEFT JOIN public.whatsapp_grupos g ON g.grupo_jid = a.grupo_jid
ON CONFLICT (id_usuario) DO UPDATE SET nombre = EXCLUDED.nombre, hora_corte = EXCLUDED.hora_corte, direccion = EXCLUDED.direccion, fecha_activacion = EXCLUDED.fecha_activacion, celular = EXCLUDED.celular, comercial = EXCLUDED.comercial, email = EXCLUDED.email, lleva_bodega = EXCLUDED.lleva_bodega, lleva_dropoff = EXCLUDED.lleva_dropoff, paga_colecta = EXCLUDED.paga_colecta, tope_maximo = EXCLUDED.tope_maximo, grupo_jid = EXCLUDED.grupo_jid, grupo_nombre = EXCLUDED.grupo_nombre, activo = EXCLUDED.activo, visto_por_ultima_vez = EXCLUDED.visto_por_ultima_vez, actualizado_en = EXCLUDED.actualizado_en, ultimo_sync_id = EXCLUDED.ultimo_sync_id;

UPDATE public.sellers_activos SET activo = false, actualizado_en = now() WHERE activo AND ultimo_sync_id <> '{{ $execution.id }}';

COMMIT;

SELECT count(*) AS sellers_consolidados FROM public.sellers_activos WHERE activo;

