const originales = $items('Normalizar grupos WhatsApp');
const cande = $items('Obtener chats label Cande');
const esteban = $items('Obtener chats label Esteban');

function lista(valor) {
  if (Array.isArray(valor)) return valor.flatMap(lista);
  if (!valor || typeof valor !== 'object') return [];
  for (const clave of ['data', 'chats', 'items', 'results', 'body']) {
    if (valor[clave] != null) {
      const encontrada = lista(valor[clave]);
      if (encontrada.length) return encontrada;
    }
  }
  return [valor];
}

function jidDe(valor) {
  if (typeof valor === 'string') return decodeURIComponent(valor);
  if (!valor || typeof valor !== 'object') return '';
  if (typeof valor._serialized === 'string') return valor._serialized;
  if (typeof valor.serialized === 'string') return valor.serialized;
  if (typeof valor.user === 'string' && typeof valor.server === 'string') return `${valor.user}@${valor.server}`;
  for (const clave of ['id', 'JID', 'jid', 'chatId', 'chat_id']) {
    const encontrado = jidDe(valor[clave]);
    if (encontrado) return encontrado;
  }
  return '';
}

function ids(items) {
  const salida = new Set();
  for (const item of items) {
    for (const chat of lista(item.json)) {
      const id = jidDe(chat);
      if (id) salida.add(id);
    }
  }
  return salida;
}

const idsCande = ids(cande);
const idsEsteban = ids(esteban);

return originales.map((item) => {
  const grupo = item.json;
  const jid = String(grupo.grupo_jid);
  const labels = [];
  if (idsCande.has(jid)) labels.push({ id: '9', name: 'Cande' });
  if (idsEsteban.has(jid)) labels.push({ id: '17', name: 'Esteban' });
  return { json: { ...grupo, labels_waha: JSON.stringify(labels) } };
});
